import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.BM5YPQmL.js";const k=JSON.parse('{"title":"البدء السريع: أول فيديو في 10 دقائق","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/quick-start.md","filePath":"ar/guide/quick-start.md"}'),n={name:"ar/guide/quick-start.md"};function o(l,s,r,h,p,d){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="البدء-السريع-أول-فيديو-في-10-دقائق" tabindex="-1">البدء السريع: أول فيديو في 10 دقائق <a class="header-anchor" href="#البدء-السريع-أول-فيديو-في-10-دقائق" aria-label="Permalink to &quot;البدء السريع: أول فيديو في 10 دقائق&quot;">​</a></h1><p>ستصنع في هذا الدليل حلقة مدتها 30 ثانية من قالب قطاعي، وتعاينها دون تسجيل، ثم تضيف صوتك وتصدّرها. تحتاج إلى <a href="./installation.html">تثبيت</a> ReelForge ونجاح الأمر <code>reelforge doctor</code>. تستخدم الأوامر هنا <code>reelforge</code>؛ اكتب على Windows <code>reelforge.cmd</code>، وعلى macOS وLinux <code>./reelforge</code>.</p><h2 id="_1-أنشئ-حلقة-من-قالب-دقيقة-واحدة" tabindex="-1">1. أنشئ حلقة من قالب (دقيقة واحدة) <a class="header-anchor" href="#_1-أنشئ-حلقة-من-قالب-دقيقة-واحدة" aria-label="Permalink to &quot;1. أنشئ حلقة من قالب (دقيقة واحدة)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> healthcare</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> patient-journey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lang</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ar</span></span></code></pre></div><p>ينشئ الأمر الملف <code>episodes/clinic-intro/episode.yaml</code> وفيه نص ومشاهد وcues تقديرية (draft)، فيمكنك معاينة الحلقة فوراً. استخدم <code>--lang en</code> لتعليق صوتي بالإنجليزية. يعرض <a href="./../reference/packs.html">فهرس الحزم</a> كل الحزم والقوالب، وتقدم لوحة التحكم الخيار نفسه عبر <strong>+ New episode</strong> ثم <strong>Start from template</strong>.</p><p>تفضّل البدء من الصفر؟ ينشئ الأمر <code>reelforge new ep10 --series &quot;SYSTEM DESIGN&quot;</code> قالباً مشروحاً بالتعليقات، أو انقر <strong>+ New episode</strong> في لوحة التحكم (<code>start.bat</code> أو <code>./start.sh</code>).</p><h2 id="_2-افتح-المحرر-واجعل-الحلقة-لك-4-دقائق" tabindex="-1">2. افتح المحرر واجعل الحلقة لك (4 دقائق) <a class="header-anchor" href="#_2-افتح-المحرر-واجعل-الحلقة-لك-4-دقائق" aria-label="Permalink to &quot;2. افتح المحرر واجعل الحلقة لك (4 دقائق)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span></span></code></pre></div><ul><li>عدّل الأسطر في تبويب <strong>Script</strong> على اليسار. اجعل في كل سطر <strong>جملة منطوقة واحدة</strong>، بنحو 2.3 كلمة في الثانية. السطر الأول هو الافتتاحية (hook) التي تشد المشاهد.</li><li>انقر على عنصر في مساحة العمل وغيّر نصه من لوحة الخصائص، أو انقر عليه مرتين لتعديله في مكانه. الكلمات بين <code>**</code> تأخذ لون التمييز: <code>**Duplicate** Charge</code>.</li><li>لجعل عنصر يظهر عند كلمة، ضع مؤشر التشغيل على تلك الكلمة وانقر الزر <strong>target</strong> بجانب <strong>Enter at</strong>. يكتب المحرر زمناً مثل <code>l3:&#39;desk&#39;</code> يبقى مرتبطاً بالكلمة حتى بعد إعادة التسجيل.</li><li>يضيف <strong>Insert</strong> مكوّناً (أو اسحب مكوّناً إلى مساحة العمل). واسحب المقاطع على الخط الزمني لإعادة توقيتها، فهي تلتصق بكلماتك.</li></ul><p>يُحفظ كل تعديل في <code>episode.yaml</code> أولاً بأول، مع الحفاظ على التعليقات.</p><h2 id="_3-افحصها-دقيقة-واحدة" tabindex="-1">3. افحصها (دقيقة واحدة) <a class="header-anchor" href="#_3-افحصها-دقيقة-واحدة" aria-label="Permalink to &quot;3. افحصها (دقيقة واحدة)&quot;">​</a></h2><p>انتقل إلى <strong>Review</strong> (‏<strong>Alt+3</strong>). تأتي كل مشكلة، مثل نص يتجاوز صندوقه أو عنصر تحت أزرار المنصة، مع تلميح لإصلاحها، وبالنقر عليها تنتقل إلى العنصر. ومن سطر الأوامر:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> l1+1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> l3+1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # PNG frames in episodes/clinic-intro/out/snaps</span></span></code></pre></div><h2 id="_4-سجّل-وحاذِ-3-دقائق" tabindex="-1">4. سجّل وحاذِ (3 دقائق) <a class="header-anchor" href="#_4-سجّل-وحاذِ-3-دقائق" aria-label="Permalink to &quot;4. سجّل وحاذِ (3 دقائق)&quot;">​</a></h2><p>سجّل نفسك وأنت تقرأ النص بأي تطبيق (الهاتف أو Audacity أو OBS…)، واترك وقفة قصيرة بين الجمل. انقر <strong>Upload voice</strong> في لوحة التحكم (تُحوَّل ملفات WAV وMP3 وM4A وOGG وOPUS وFLAC إلى <code>voice.wav</code>)، أو احفظ الملف باسم <code>episodes/clinic-intro/voice.wav</code>. ثم حدد الـ cues:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span></span></code></pre></div><p>افتح وضع <strong>Cues</strong> (‏<strong>Alt+2</strong>)، واستمع مرة واحدة إلى النهاية، وأصلح أي سطر بالسمع (اضغط <strong>Space</strong> عند بداية السطر). يشرح دليل <a href="./timing.html">التوقيت والـ cues والمحاذاة</a> التفاصيل.</p><h2 id="_5-صدّر-الفيديو-دقيقة-للبدء" tabindex="-1">5. صدّر الفيديو (دقيقة للبدء) <a class="header-anchor" href="#_5-صدّر-الفيديو-دقيقة-للبدء" aria-label="Permalink to &quot;5. صدّر الفيديو (دقيقة للبدء)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> render</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clinic-intro</span></span></code></pre></div><p>أو انقر <strong>Render</strong> (‏**⌘/Ctrl+Enter**) في المحرر. عند الانتهاء، ارفع الملف <code>episodes/clinic-intro/out/clinic-intro.share.mp4</code> مع نص المنشور والوسوم من <code>out/publish.md</code>. لم تسجّل بعد؟ يصدّر الأمر <code>reelforge render clinic-intro --silent</code> نسخة للمعاينة بالتوقيت التقديري.</p><blockquote><p>تفضّل العمل مع مساعد ذكاء اصطناعي؟ راجع <a href="./ai.html">التكامل مع الذكاء الاصطناعي</a>. يستطيع المساعد أن يكتب النص ويبني المشاهد ويفحص الإطارات نيابةً عنك عبر خادم MCP.</p></blockquote>`,21)])])}const g=i(n,[["render",o]]);export{k as __pageData,g as default};
